<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { UserRound, Sparkles, WalletCards, ArrowUpRight, ArrowDownLeft } from 'lucide-vue-next';
import { api, money } from '../../frontend-shared/api';
import { memberApi, memberToken, setMemberToken, randomKey, dateLabel, stateLabel, type Data } from '../../frontend-shared/commerce';
const props=defineProps<{member:Data|null}>();
const emit=defineEmits<{updated:[Data|null],address:[Data]}>();
const tab=ref('profile'),busy=ref(false),error=ref(''),notice=ref(''),register=ref(false);
const phone=ref(''),password=ref(''),name=ref(props.member?.name||''),birthday=ref(props.member?.birthday||'');
const addresses=ref<Data[]>([]),benefits=ref<Data>({coupons:[],claims:[],rewards:[],tasks:[],redemptions:[]}),ledgers=ref<Data[]>([]),devices=ref<Data[]>([]),places=ref<Data[]>([]);
const addressForm=ref<Data|null>(null),addressId=ref<number|null>(null);
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){
 if(!memberToken())return;
 const [m,a,b,l,d,c]=await Promise.all([memberApi('members/me'),memberApi<Data[]>('addresses'),memberApi('benefits'),memberApi<Data[]>('ledgers'),memberApi<Data[]>('members/devices'),api<Data>('delivery/config')]);
 emit('updated',m);name.value=m.name;birthday.value=m.birthday||'';addresses.value=a;benefits.value=b;ledgers.value=l;devices.value=d;places.value=c.places||[];
}
async function authenticate(){await action(async()=>{const r=await memberApi(`members/${register.value?'register':'login'}`,'POST',{phone:phone.value,password:password.value,device_name:'浏览器设备'});setMemberToken(r.token);password.value='';emit('updated',r.member);await load();});}
async function logout(){await action(async()=>{await memberApi('members/logout','POST');setMemberToken('');emit('updated',null);});}
async function saveProfile(){await action(async()=>{const r=await memberApi('members/me','PATCH',{name:name.value,birthday:birthday.value||null});emit('updated',r);await load();notice.value='会员资料已保存';});}
function editAddress(a?:Data){addressId.value=a?.id||null;addressForm.value=a?{...a.data,is_default:a.is_default}:{contact:props.member?.name||'',phone:props.member?.phone||'',title:'',detail:'',latitude:0,longitude:0,coordinate_system:'GCJ_02',is_default:false};}
function selectPlace(e:Event){const p=places.value.find(x=>x.id===(e.target as HTMLSelectElement).value);if(p&&addressForm.value)Object.assign(addressForm.value,{title:p.title,detail:p.address,latitude:p.latitude,longitude:p.longitude,coordinate_system:p.coordinate_system});}
async function saveAddress(){await action(async()=>{await memberApi(addressId.value?`addresses/${addressId.value}`:'addresses',addressId.value?'PUT':'POST',addressForm.value);addressForm.value=null;await load();notice.value='收货地址已保存';});}
async function choose(a:Data){await action(async()=>{await memberApi(`addresses/${a.id}/use`,'POST');emit('address',{...a.data,id:a.id});notice.value='已选择此收货地址';});}
async function claim(path:string){await action(async()=>{await memberApi(path,'POST');await load();notice.value='领取成功';});}
const redeemKeys:Record<number,string>={};
async function redeem(r:Data){if(!confirm(`确认使用 ${r.points_cost} 积分兑换「${r.title}」？`))return;await action(async()=>{await memberApi('rewards/redeem','POST',{reward_id:r.id,request_key:redeemKeys[r.id]||(redeemKeys[r.id]=randomKey())});delete redeemKeys[r.id];await load();notice.value='兑换成功，请向店员出示兑换码';});}
async function removeAddress(a:Data){if(!confirm('确认删除这个收货地址？'))return;await action(async()=>{await memberApi(`addresses/${a.id}`,'DELETE');await load();});}
async function revoke(d:Data){await action(async()=>{await memberApi(`members/devices/${d.id}`,'DELETE');if(d.current){setMemberToken('');emit('updated',null);}else await load();});}
onMounted(()=>action(load));
</script>
<template>
 <section class="cx-member">
  <p v-if="error" class="cx-error" role="alert">{{error}}</p><p v-if="notice" class="cx-note" role="status">{{notice}}</p>
  <form v-if="!member" class="cx-card cx-login" @submit.prevent="authenticate"><span class="cx-login-icon" aria-hidden="true"><UserRound :size="28" /></span>
   <p class="cx-eyebrow">美味与成长，都在这里</p><h2>{{register?'注册本店会员':'登录本店会员'}}</h2><p class="cx-muted">登录后可查看订单、管理地址，享受本店的会员权益。</p><p class="cx-help">各门店的会员、积分和储值余额独立。</p>
   <label class="cx-field"><span>手机号</span><input v-model="phone" type="tel" inputmode="tel" required pattern="1[3-9][0-9]{9}" autocomplete="username" placeholder="11 位手机号"></label>
   <label class="cx-field"><span>密码（至少10位）</span><input v-model="password" type="password" required minlength="10" maxlength="100" :autocomplete="register?'new-password':'current-password'"></label>
   <button class="cx-primary" :disabled="busy">{{busy?'正在处理…':register?'注册并登录':'登录'}}</button><button type="button" class="cx-secondary" @click="register=!register">{{register?'已有账号，去登录':'没有账号，去注册'}}</button>
  </form>
  <template v-else>
   <div class="cx-member-hero"><div class="cx-row"><div class="cx-member-identity"><span class="cx-avatar" aria-hidden="true">{{(member.name||'会').slice(0,1)}}</span><div><span class="cx-tag">{{member.level}}</span><h2>{{member.name||'新会员'}}</h2><span class="cx-muted">{{member.phone}}</span></div></div><button class="cx-secondary" :disabled="busy" @click="logout">退出登录</button></div><div class="cx-member-balances"><div><span class="cx-asset-label"><Sparkles :size="16" aria-hidden="true" />积分</span><strong class="cx-balance">{{member.points}}</strong><span class="cx-help">可用于积分商城兑换</span></div><div><span class="cx-asset-label"><WalletCards :size="16" aria-hidden="true" />储值余额</span><strong class="cx-balance"><small>¥</small>{{money(member.wallet_cents)}}</strong><span class="cx-help">储值暂不支持在线支付</span></div></div></div>
   <nav class="cx-nav cx-member-nav" aria-label="会员功能"><button v-for="item in [['profile','资料'],['addresses','地址簿'],['coupons','优惠券'],['rewards','积分商城'],['tasks','成长任务'],['ledgers','资产明细'],['devices','登录设备']]" :key="item[0]" :class="{active:tab===item[0]}" :aria-current="tab===item[0]?'page':undefined" @click="tab=item[0]">{{item[1]}}</button></nav>
   <form v-if="tab==='profile'" class="cx-card" @submit.prevent="saveProfile"><h3>会员资料</h3><label class="cx-field"><span>姓名 / 昵称</span><input v-model="name" maxlength="60" required></label><label class="cx-field"><span>生日（登记后不可自行更改）</span><input v-model="birthday" type="date" :disabled="!!member.birthday"></label><p class="cx-help">累计完成订单金额 ¥{{money(member.lifetime_cents)}}。等级与积分按门店规则累计，该金额不代表已收款金额。</p><button class="cx-primary" :disabled="busy">保存资料</button></form>
   <div v-if="tab==='addresses'"><div class="cx-row"><h3>我的收货地址</h3><button class="cx-primary" @click="editAddress()">新增地址</button></div><div v-for="a in addresses" :key="a.id" class="cx-card"><div class="cx-row"><h3>{{a.data.title}}</h3><span v-if="a.is_default" class="cx-tag">默认</span></div><p>{{a.data.detail}}</p><p class="cx-muted">{{a.data.contact}} · {{a.data.phone}}</p><div class="cx-actions"><button class="cx-primary" :disabled="busy" @click="choose(a)">用于本次配送</button><button class="cx-secondary" @click="editAddress(a)">编辑</button><button class="cx-danger" :disabled="busy" @click="removeAddress(a)">删除</button></div></div><p v-if="!addresses.length" class="cx-empty">还没有收货地址，最多可保存20个。</p></div>
   <div v-if="tab==='coupons'"><h3>领券中心</h3><div v-for="c in benefits.coupons" :key="c.id" class="cx-card"><div class="cx-row"><div><h3>{{c.title}}</h3><span class="cx-price">减 ¥{{money(c.amount_cents)}}</span><p class="cx-muted">满 ¥{{money(c.minimum_cents)}} 可用{{c.birthday_only?' · 生日当月专享':''}}</p><small>{{dateLabel(c.expires_at)}} 到期</small></div><button class="cx-primary" :disabled="busy||benefits.claims.some((a:Data)=>a.coupon_id===c.id)" @click="claim(`coupons/${c.id}/claim`)">{{benefits.claims.some((a:Data)=>a.coupon_id===c.id)?'已领取':'领取'}}</button></div></div><h3>我的优惠券</h3><div v-for="c in benefits.claims" :key="c.id" class="cx-card"><div class="cx-row"><strong>{{c.snapshot.title}}</strong><span class="cx-tag">{{new Date(c.snapshot.expires_at).getTime()<Date.now()?'已过期':stateLabel(c.status)}}</span></div><p>满 ¥{{money(c.snapshot.minimum_cents)}} 减 ¥{{money(c.snapshot.amount_cents)}}</p></div><p v-if="!benefits.coupons.length&&!benefits.claims.length" class="cx-empty">门店尚未发放优惠券。</p></div>
   <div v-if="tab==='rewards'"><h3 class="cx-tab-title">积分商城</h3><p class="cx-note">兑换后请向店员出示兑换码，核销后领取奖品。</p><div v-for="r in benefits.rewards" :key="r.id" class="cx-card"><h3>{{r.title}}</h3><p class="cx-muted">{{r.description}}</p><div class="cx-row"><strong>{{r.points_cost}} 积分 · 剩余 {{r.stock}}</strong><button class="cx-primary" :disabled="busy||r.stock<1||member.points<r.points_cost" @click="redeem(r)">兑换</button></div></div><p v-if="!benefits.rewards.length" class="cx-empty">门店尚未上架积分奖品。</p><h3>兑换记录</h3><div v-for="r in benefits.redemptions" :key="r.id" class="cx-card"><div class="cx-row"><strong>{{r.title}}</strong><span class="cx-tag">{{r.status==='PENDING'?'待核销':stateLabel(r.status)}}</span></div><p>兑换码：<strong>{{r.code}}</strong></p><small>{{dateLabel(r.created_at)}}</small></div><p v-if="!benefits.redemptions.length" class="cx-empty">还没有兑换记录，获得积分后再来看看。</p></div>
   <div v-if="tab==='tasks'"><h3 class="cx-tab-title">成长任务</h3><div v-for="t in benefits.tasks" :key="t.id" class="cx-card"><h3>{{t.title}}</h3><p class="cx-muted">奖励 {{t.points_reward}} 积分 · 进度 {{t.kind==='SPEND'?'¥'+money(t.progress):t.progress}} / {{t.kind==='SPEND'?'¥'+money(t.target):t.target}}</p><progress class="cx-task-progress" :value="Math.min(t.progress,t.target)" :max="t.target" :aria-label="`${t.title}完成进度`"></progress><button class="cx-primary" :disabled="busy||t.claimed||t.progress<t.target" @click="claim(`tasks/${t.id}/claim`)">{{t.claimed?'已领取':'领取奖励'}}</button></div><p v-if="!benefits.tasks.length" class="cx-empty">暂时没有成长任务。</p></div>
   <div v-if="tab==='ledgers'"><h3 class="cx-tab-title">资产明细</h3><p class="cx-note">查看积分与储值余额的变动，包括门店人工调整。储值暂不支持在线支付，在线充值和退款尚未开通。</p><div v-for="l in ledgers" :key="l.id" class="cx-card cx-ledger"><div class="cx-row"><div class="cx-ledger-kind"><span class="cx-ledger-icon" :class="{'is-increase':l.delta>0}"><component :is="l.delta>0?ArrowDownLeft:ArrowUpRight" :size="20" aria-hidden="true" /></span><strong>{{l.kind==='POINTS'?'积分':'储值余额'}}</strong></div><strong class="cx-ledger-amount" :class="{'is-increase':l.delta>0}">{{l.delta>0?'+':l.delta<0?'−':''}}{{l.kind==='POINTS'?Math.abs(l.delta):'¥'+money(Math.abs(l.delta))}}</strong></div><p>{{l.reason}}</p><small class="cx-muted">{{dateLabel(l.created_at)}} · 变动后 {{l.kind==='POINTS'?l.balance:'¥'+money(l.balance)}}</small></div><p v-if="!ledgers.length" class="cx-empty">暂无资产变动。</p></div>
   <div v-if="tab==='devices'"><h3 class="cx-tab-title">登录设备</h3><p class="cx-note">登录凭据仅对应本店，有效期30天。移除设备后，该设备需要重新登录。</p><div v-for="d in devices" :key="d.id" class="cx-card"><div class="cx-row"><div><h3>{{d.device_name}} {{d.current?'（当前）':''}}</h3><small>{{dateLabel(d.created_at)}} 登录</small></div><button class="cx-danger" :disabled="busy" @click="revoke(d)">退出此设备</button></div></div></div>
  </template>
  <div v-if="addressForm" class="cx-overlay" @click.self="addressForm=null"><form class="cx-dialog" role="dialog" aria-modal="true" aria-label="编辑收货地址" @submit.prevent="saveAddress"><div class="cx-dialog-header"><h2>收货地址</h2><button type="button" class="cx-secondary" @click="addressForm=null">关闭</button></div><label v-if="places.length" class="cx-field"><span>选择门店登记的常送地点</span><select @change="selectPlace"><option value="">请选择</option><option v-for="p in places" :value="p.id">{{p.title}}</option></select></label><label class="cx-field"><span>收货点名称</span><input v-model="addressForm.title" required maxlength="120"></label><label class="cx-field"><span>详细地址 / 楼栋门牌</span><input v-model="addressForm.detail" required maxlength="500"></label><div class="cx-grid"><label class="cx-field"><span>联系人</span><input v-model="addressForm.contact" required maxlength="60"></label><label class="cx-field"><span>手机号</span><input v-model="addressForm.phone" required type="tel" pattern="1[3-9][0-9]{9}"></label></div><p class="cx-help">配送范围按地址坐标计算。可选择门店常送地点，或填写收货地点的准确坐标。</p><div class="cx-grid"><label class="cx-field"><span>纬度</span><input v-model.number="addressForm.latitude" type="number" step="any" min="-90" max="90" required></label><label class="cx-field"><span>经度</span><input v-model.number="addressForm.longitude" type="number" step="any" min="-180" max="180" required></label></div><label class="cx-field"><span>坐标来源</span><select v-model="addressForm.coordinate_system"><option value="GCJ_02">高德 / 腾讯坐标</option><option value="BD_09">百度坐标</option><option value="WGS_84">GPS 原始坐标</option></select></label><label><input v-model="addressForm.is_default" type="checkbox"> 设为默认地址</label><p v-if="error" class="cx-error">{{error}}</p><div class="cx-actions"><button class="cx-primary" :disabled="busy">保存地址</button></div></form></div>
 </section>
</template>
